//! 🧪️ Shared original Energy source witnesses observe exact native receiving, projection and retirement receipts.
use semio_framework_value::{DslValue,RetirementDemand,retained_clone::{RetainedCloneRef,RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep},retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_snapshot_projection::snapshot_projection::{SnapshotProjection,SnapshotProjectionCursor};
use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeReceive,NativeReceiver};
use super::PostFixture;
pub(crate) fn corpus()->serde_json::Value{serde_json::from_str(include_str!("../../../../../🧪️tests/🧫️fixtures/📸️snapshot/🧳️state/🔣️.json")).unwrap()}
pub(crate) fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"actual original Energy frontier exceeds4096: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
struct OriginalConstruction{grant:RetainedCloneGrant,issued:bool}
impl semio_framework_value_native_owned::native_decoding::NativeDecodeConstructionRecipient for OriginalConstruction{
 fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,semio_framework_value::ValueError>{assert!(!self.issued);assert!(semio_framework_value::retained_clone::retained_clone_grant_admits(self.grant,d));self.issued=true;Ok(self.grant)}
 fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),semio_framework_value::ValueError>{assert!(self.issued);assert_eq!(g,self.grant);assert!(p.fits(g));Ok(())}
}
fn advance_original<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,original:semio_framework_value::retained_clone::RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedCloneStep,semio_framework_value::ValueError>{let mut recipient=OriginalConstruction{grant:g,issued:false};control.with_construction_recipient(&mut recipient,|control|receiver.advance(original,control,4096,g))}
pub(crate) fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);(result,(heap.requested_bytes,heap.released_bytes))}
pub(crate) fn drain<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).unwrap_or_else(|_|panic!("actual State owner supports controlled retirement"));for _ in 0..1000000{if owner.terminal_is_empty(){return;}let g=grant(owner.next_demand(4096).unwrap());let(step,heap)=observe(||owner.step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}panic!("State owner did not settle original retirement");}
pub(crate) fn source<T:RetireOwned+Sync>(value:T)->RetainedCloneSource<T>{let d=RetainedCloneSource::<T>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<T>::constructor_copy_bytes(),..grant(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})};RetainedCloneSource::admit_owned(value,(),g).unwrap_or_else(|_|panic!("original State source admission")).0}
pub(crate) fn wire(json:&serde_json::Value)->DslValue{match json{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(v)=>DslValue::Bool(*v),serde_json::Value::String(v)=>DslValue::String(v.clone()),serde_json::Value::Number(v)=>DslValue::Number(if let Some(v)=v.as_u64(){semio_framework_value::Number::UInt(v)}else{semio_framework_value::Number::Float(v.as_f64().unwrap())}),serde_json::Value::Array(v)=>DslValue::Array(v.iter().map(wire).collect()),serde_json::Value::Object(v)=>DslValue::Object(v.iter().map(|(key,value)|(key.clone(),wire(value))).collect())}}
pub(crate) fn receive<T:NativeReceive<DslValue>>(json:&serde_json::Value)->T{receive_with_ownership(json,1<<24)}
pub(crate) fn receive_with_ownership<T:NativeReceive<DslValue>>(json:&serde_json::Value,maximum_bytes:usize)->T{receive_with_ledger(json,Some(maximum_bytes))}
/// 🛬️ The retained source admits exactly each granted physical birth into the same cumulative ledger, as the original mounted Job does.
pub(crate) fn receive_retained<T:NativeReceive<DslValue>>(json:&serde_json::Value)->T{receive_with_ledger(json,None)}
fn receive_with_ledger<T:NativeReceive<DslValue>>(json:&serde_json::Value,maximum_bytes:Option<usize>)->T{
 let original=source(wire(json));let d=T::receive_birth_demand();let(mut receiver,p)=T::begin_receive(grant(d)).unwrap();assert!(p.fits(grant(d)));let mut callback=|_|true;let mut control=match maximum_bytes{Some(bytes)=>NativeDecodeControl::new(bytes,&mut callback),None=>NativeDecodeControl::new_retained(&mut callback)};let mut physical_births=0usize;let mut original_turns=0usize;let mut original_items=0usize;
 for _ in 0..1000000{if receiver.output_ready(){break;}let d=receiver.demands(original.borrow(),4096).unwrap();assert!(d.copy_bytes<=4096,"{} native receiving turn exceeds4096: {d:?}",std::any::type_name::<T>());let g=grant(d);let mut denied=g;denied.maximum_items=0;let(step,heap)=observe(||advance_original(&mut receiver,original.borrow(),&mut control,denied).unwrap());assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap,(0,0));if maximum_bytes.is_none(){control.admit_turn_capacity(d.capacity_bytes).unwrap();}let(step,heap)=observe(||advance_original(&mut receiver,original.borrow(),&mut control,g));physical_births+=heap.0;original_turns+=1;let step=step.unwrap_or_else(|error|panic!("[DEBUG] original receiving {}: owned={} physical_births={} demand={d:?} refusal={error:?}",std::any::type_name::<T>(),control.owned_bytes(),physical_births));original_items+=step.progress().copied_items;assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert_eq!(control.owned_bytes(),physical_births);if maximum_bytes.is_none(){assert_eq!(control.maximum_bytes(),physical_births);} }
 assert!(receiver.output_ready(),"original receiver exhausted turns={original_turns} funded_items={original_items} capacity={physical_births} next={:?}",receiver.demands(original.borrow(),4096));let g=grant(receiver.take_demand().unwrap());let((output,p),heap)=observe(||receiver.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));receiver.begin_close();for _ in 0..100000{if receiver.terminal_is_empty(){break;}let g=grant(receiver.close_demands(4096).unwrap());let(step,heap)=observe(||receiver.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(receiver.terminal_is_empty());drain(original);output
}
pub(crate) fn denied_axes(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut result=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{result.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes>0{result.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes>0{result.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}if d.depth>0{result.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g});}result}
pub(crate) fn central_fragment<P:RetireOwned+Sync,D:protocol::mutation::retained::RetainedDiffFragment<P>>(patch:&RetainedCloneSource<D>,original:semio_framework_value::RetainedCloneRef<'_,P>,post:&mut PostFixture<P>)->bool{
 use protocol::mutation::retained::{begin_retained_diff,retained_diff_birth_demand,preflight_retained_diff,commit_retained_diff,RetainedDiffPreflightStep};
 let d=retained_diff_birth_demand::<P,D>();let g=grant(d);let((mut owner,p),heap)=observe(||begin_retained_diff::<P,D>(g).unwrap());assert!(p.fits(g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut admitted=None;
 for _ in 0..100000{let d=owner.preflight_demand(patch.borrow(),original,post.borrow(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||preflight_retained_diff(&mut owner,patch.borrow(),original,post.borrow(),4096,denied,&mut control).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.preflight_demand(patch.borrow(),original,post.borrow(),4096).unwrap(),d);}let(step,heap)=observe(||preflight_retained_diff(&mut owner,patch.borrow(),original,post.borrow(),4096,g,&mut control).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));match step{RetainedDiffPreflightStep::Admitted(_,messages)=>{assert!(messages.is_empty());admitted=Some(true);break;},RetainedDiffPreflightStep::Refused(_,messages)=>{assert!(messages.is_empty());admitted=Some(false);break;},_=>{}}}
 let admitted=admitted.expect("original central Zone preflight settles");if admitted{owner.inverse_admission(patch.borrow(),original).unwrap();let mut complete=false;for _ in 0..100000{let d=owner.commit_demand(patch.borrow(),original,post.mutable_read(),4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||commit_retained_diff(&mut owner,patch.borrow(),original,post,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.commit_demand(patch.borrow(),original,post.mutable_read(),4096).unwrap(),d);}let(step,heap)=observe(||commit_retained_diff(&mut owner,patch.borrow(),original,post,g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));if matches!(step,RetainedCloneStep::Complete(_)){complete=true;break;}}assert!(complete);}
 owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){break;}let d=owner.close_demand(4096).unwrap();let g=grant(d);for denied in denied_axes(g,d){let(step,heap)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.close_demand(4096).unwrap(),d);}let(step,heap)=observe(||owner.close_step(g).unwrap());assert!(step.progress().fits(g));assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));}assert!(owner.terminal_is_empty());admitted
}
pub(crate) fn projected_source<T:RetireOwned+Sync>(value:Box<T>)->RetainedCloneSource<T,Box<T>>{let d=RetainedCloneSource::<T,Box<T>>::constructor_demand::<()>();let g=grant(RetirementDemand{copy_bytes:RetainedCloneSource::<T,Box<T>>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()});RetainedCloneSource::<T,Box<T>>::admit_borrowed(value,Box::as_ref,g).unwrap_or_else(|_|panic!("original projected authority admission")).0}
pub(crate) fn assert_portable_value(actual:DslValue,expected:&serde_json::Value){let actual:serde_json::Value=serde_json::from_str(&semio_framework_pack_json::to_json_string(&actual)).unwrap();fn equivalent(actual:&serde_json::Value,expected:&serde_json::Value){match(actual,expected){(serde_json::Value::Number(a),serde_json::Value::Number(b))=>assert_eq!(a.as_f64(),b.as_f64()),(serde_json::Value::Array(a),serde_json::Value::Array(b))=>{assert_eq!(a.len(),b.len());for(a,b)in a.iter().zip(b){equivalent(a,b);}},(serde_json::Value::Object(a),serde_json::Value::Object(b))=>{assert_eq!(a.len(),b.len());for(key,value)in a{equivalent(value,b.get(key).expect("same portable member"));}},_=>assert_eq!(actual,expected)}}equivalent(&actual,expected);}
pub(crate) fn project_record<T:SnapshotProjection<Output=Box<T>>>(original:RetainedCloneRef<'_,T>)->Box<T>{let(mut cursor,_)=T::begin_projection(grant(T::projection_birth_demand())).unwrap();for _ in 0..100000{if cursor.ready(){break;}let g=grant(cursor.demands(original,4096).unwrap());let(s,h)=observe(||cursor.advance(original,4096,g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(cursor.ready());let g=grant(cursor.take_demand().unwrap());let((result,p),h)=observe(||cursor.take(g).unwrap().unwrap());assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));cursor.begin_close();for _ in 0..100000{if cursor.terminal_is_empty(){break;}let g=grant(cursor.close_demands(4096).unwrap());let(s,h)=observe(||cursor.close_step(g).unwrap());assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(cursor.terminal_is_empty());result}
